import { afterAll, beforeAll, describe, expect, it } from \"vitest\";
import { eq } from \"drizzle-orm\";
import { subscribe } from \"@/lib/event-bus\";
import { importIssuesSchema } from \"@/schemas/issue-import\";
import { activityEvents, getDb, issueLabels, labels, notifications, webhookDeliveries } from \"@/server/db\";
import { registerEventHandlers, unregisterEventHandlers } from \"@/server/services/event-registry\";
import { createIssue, importIssues } from \"@/server/services/issue-service\";
import { search } from \"@/server/services/search-service\";
import { getUsage, recomputeUsage } from \"@/server/services/usage-service\";
import { createTenant, issueInput, useTemporaryDatabase } from \"./_support/fixtures\";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => { unregisterEventHandlers(); cleanup(); });

describe(\"issue imports\", () => {
  it(\"imports in order, indexes and audits once, and replays the persisted result\", async () => {
    const tenant = await createTenant(\"imports\");
    const actor = tenant.actors.owner;
    const input = importIssuesSchema.parse({
      orgId: tenant.org.id, projectId: tenant.project.id, importKey: \"upload-123\",
      rows: [
        { title: \"Needle first\", assigneeEmail: \"MEMBER@IMPORTS.TEST\", labels: [\"Bug\", \"Bug\"] },
        { title: \"Needle second\", labels: [\"Bug\", \"bug\"], status: \"done\" },
      ],
    });
    const events: string[] = [];
    const offCreated = subscribe(\"issue.created\", () => { events.push(\"created\"); });
    const offImported = subscribe(\"issues.imported\", (event) => { events.push(event.issueIds.join(\",\")); });
    try {
      const result = await importIssues(actor, input);
      expect(result.replayed).toBe(false);
      expect(result.issues.map((issue) => issue.number)).toEqual([1, 2]);
      expect(result.issues[0]?.assigneeId).toBe(tenant.userIds.member);
      expect(result.issues.map((issue) => issue.labelIds.length)).toEqual([1, 2]);
      expect(events).toEqual([result.issues.map((issue) => issue.id).join(\",\")]);
      expect(getDb().select().from(labels).where(eq(labels.orgId, tenant.org.id)).all()).toHaveLength(2);
      expect(getDb().select().from(issueLabels).where(eq(issueLabels.orgId, tenant.org.id)).all()).toHaveLength(3);
      expect((await search(actor, { orgId: tenant.org.id, q: \"Needle\", limit: 25, cursor: null })).total).toBe(2);
      const usage = await getUsage(actor, tenant.org.id);
      expect(usage.issuesUsed).toBe(2);
      expect((await recomputeUsage(tenant.org.id)).issuesUsed).toBe(usage.issuesUsed);
      const audit = getDb().select().from(activityEvents).where(eq(activityEvents.orgId, tenant.org.id)).all();
      expect(audit).toHaveLength(1);
      expect(audit[0]).toMatchObject({ action: \"issues.imported\", actorId: actor.userId, subjectKind: \"project\", subjectId: tenant.project.id, projectId: tenant.project.id });
      expect(JSON.parse(audit[0]"'!.metadata)).toEqual({ count: 2, importKey: input.importKey });
      expect(getDb().select().from(notifications).where(eq(notifications.orgId, tenant.org.id)).all()).toHaveLength(0);
      expect(getDb().select().from(webhookDeliveries).where(eq(webhookDeliveries.orgId, tenant.org.id)).all()).toHaveLength(0);
      const replay = await importIssues(actor, { ...input, rows: [input.rows[1]!] });
      expect(replay).toEqual({ ...result, replayed: true });
      expect(events).toHaveLength(1);
      const next = await createIssue(actor, issueInput(tenant.org.id, tenant.project.id));
      expect(next.number).toBe(3);
    } finally { offCreated(); offImported(); }
  });

  it("rejects a batch over quota without creating labels or reserving the key", async () => {
    const tenant = await createTenant("import-quota", "free");
    const actor = tenant.actors.owner;
    const input = importIssuesSchema.parse({ orgId: tenant.org.id, projectId: tenant.project.id, importKey: "quota-key", rows: Array.from({ length: 101 }, (_, i) => ({ title: `Issue ${i}`, labels: ["new label"] })) });
    await expect(importIssues(actor, input)).rejects.toThrow("allows no more issues");
    expect(getDb().select().from(labels).where(eq(labels.orgId, tenant.org.id)).all()).toHaveLength(0);
    const result = await importIssues(actor, { ...input, rows: input.rows.slice(0, 1) });
    expect(result.replayed).toBe(false);
  });
});
